{"refs":["alphabet","length","modulus","residue","sum_min","sum_max","target_digit","target_count"],"code":"def solve(facts):
    alphabet = facts['alphabet']
    length = facts['length']
    modulus = facts['modulus']
    residue = facts['residue']
    sum_min = facts['sum_min']
    sum_max = facts['sum_max']
    target_digit = facts['target_digit']
    target_count = facts['target_count']
    dp = {(0, 0, 0, -1): (1, 0)}
    for _ in range(length):
        nxt = {}
        for (r, s, c, last), (n, total) in dp.items():
            for d in alphabet:
                if d == last:
                    continue
                nc = c + (d == target_digit)
                ns = s + d
                if nc > target_count or ns > sum_max:
                    continue
                key = ((r * 10 + d) % modulus, ns, nc, d)
                old_n, old_total = nxt.get(key, (0, 0))
                nxt[key] = (old_n + n, old_total + total + n * d)
        dp = nxt
    count = 0
    digit_sum_total = 0
    for (r, s, c, last), (n, total) in dp.items():
        if r == residue and sum_min <= s <= sum_max and c == target_count:
            count += n
            digit_sum_total += total
    return {'count': count, 'digit_sum_total': digit_sum_total}

def check(answer, facts):
    alphabet = facts['alphabet']
    length = facts['length']
    modulus = facts['modulus']
    residue = facts['residue']
    sum_min = facts['sum_min']
    sum_max = facts['sum_max']
    target_digit = facts['target_digit']
    target_count = facts['target_count']
    counts = {}
    totals = {}
    for d in alphabet:
        c = (d == target_digit)
        s = d
        if c <= target_count and s <= sum_max:
            key = (d % modulus, s, c, d)
            counts[key] = counts.get(key, 0) + 1
            totals[key] = totals.get(key, 0) + d
    for _ in range(1, length):
        new_counts = {}
        new_totals = {}
        for (r, s, c, last), n in counts.items():
            for d in alphabet:
                if d != last:
                    ns = s + d
                    nc = c + (d == target_digit)
                    if ns <= sum_max and nc <= target_count:
                        key = ((r * 10 + d) % modulus, ns, nc, d)
                        new_counts[key] = new_counts.get(key, 0) + n
                        new_totals[key] = new_totals.get(key, 0) + totals[(r, s, c, last)] + n * d
        counts, totals = new_counts, new_totals
    expected_count = 0
    expected_total = 0
    for key, n in counts.items():
        r, s, c, last = key
        if r == residue and sum_min <= s <= sum_max and c == target_count:
            expected_count += n
            expected_total += totals[key]
    return isinstance(answer, dict) and answer.get('count') == expected_count and answer.get('digit_sum_total') == expected_total"}

